import React from 'react';

import { IUser } from 'src/services/users.service';

import { getQuestionsWithResults } from '@apps/Interview/@services/interview.service';
import {
  IQuestionInputWithAnswer,
  IQuestionSelectWithAnswer,
  IQuestionType,
  IQuestionWithAnswer,
} from '@apps/Interview/@types/interview.types';
import PageLoader from '@components/PageLoader';
import { round } from '@helpers/mathHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohAva from '@ui-kit/Ava';
import PohList from '@ui-kit/List';
import { showModal } from '@ui-kit/Modal';

interface IInterviewResultsProps {
  id_interview: number;
  showParticipants?: boolean;
}

const InterviewResults: React.FC<IInterviewResultsProps> = ({ id_interview, showParticipants }) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();

  const [results, setResults] = React.useState<IQuestionWithAnswer[]>([]);

  const load = React.useCallback(async () => {
    try {
      setIsLoading(true);

      const res = await getQuestionsWithResults(id_interview);
      setResults(res);
    } catch (e) {
      setErr(e as Error);
    } finally {
      setIsLoading(false);
    }
  }, [id_interview]);

  React.useEffect(() => {
    load();
  }, [load]);

  if (isLoading) return <PageLoader />;
  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;

  const participants: Record<number, { user: IUser; date: Date }> = {};

  const r = results.reduce<Record<number, IQuestionWithAnswer[]>>((acc, val) => {
    if (!acc[val.id]) {
      acc[val.id] = [];
    }

    if (!participants[val.user.id]) {
      participants[val.user.id] = { user: val.user, date: val.answer_date };
    }

    acc[val.id].push(val);

    return acc;
  }, {});

  return (
    <div>
      {showParticipants && (
        <section>
          <h3>Участники опроса</h3>
          <PohList
            data={Object.values(participants).map(({ user, date }) => {
              return {
                key: user.id,
                children: (
                  <div className="d-flex">
                    <PohAva src={user.photo} alt={user.name} />
                    <div className="ms-2">
                      <strong className=" d-block mb-n1">
                        {user.name} {user.surname}
                      </strong>
                      <small>{date.toLocaleString()}</small>
                    </div>
                  </div>
                ),
              };
            })}
          />
        </section>
      )}
      {Object.entries(r).map(([id_qq, oneQuestionAnswers]) => {
        const answer = oneQuestionAnswers[0];

        if (answer.isPrivate) {
          return (
            <div key={id_qq}>
              <header className="d-flex mb-2 mt-4">
                <div>
                  <h4 className="mb-n1">{answer.name}</h4>
                  <small>{answer.text}</small>
                </div>
                <small className="text-muted ms-auto">
                  {answer.isMulti
                    ? 'Выбор одного или несколькиз вариантов ответа'
                    : 'Выбор варианта'}
                </small>
              </header>
              <div className="text-muted text-center bg-light" style={{ letterSpacing: '3rem' }}>
                private
              </div>
            </div>
          );
        }

        if (answer.type === IQuestionType.Dir) {
          return <div key={id_qq}>Dir is no implemented</div>;
        }

        if (answer.type === IQuestionType.Select) {
          const variantVotes: Record<number, number> = {};
          const customs: string[] = [];

          (oneQuestionAnswers as IQuestionSelectWithAnswer[]).forEach((val) => {
            val.selectedIds.forEach((selId) => {
              if (!variantVotes[selId]) variantVotes[selId] = 0;
              variantVotes[selId]++;
            });
            if (val.customValue) customs.push(val.customValue);
          });
          return (
            <div key={id_qq}>
              <header className="d-flex mb-2 mt-4">
                <div>
                  <h4 className="mb-n1">{answer.name}</h4>
                  <small>{answer.text}</small>
                </div>
                <small className="text-muted ms-auto">
                  {answer.isMulti
                    ? 'Выбор одного или несколькиз вариантов ответа'
                    : 'Выбор варианта'}
                </small>
              </header>

              <table className="table table-condensed table-bordered table-sm">
                <thead>
                  <tr>
                    <th>Вариант</th>
                    <th>Голосов</th>
                    <th>%</th>
                  </tr>
                </thead>
                <tbody>
                  {(answer as IQuestionSelectWithAnswer).options.map((opt) => {
                    return (
                      <tr key={opt.id}>
                        <td>{opt.value}</td>
                        <td>{variantVotes[opt.id] ?? 0}</td>
                        <td>
                          {round(((variantVotes[opt.id] ?? 0) / answer.options.length) * 100)}%
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
              {answer.isCustom && customs.length > 0 && <p>А так же: {customs.join(', ')}</p>}
            </div>
          );
        }
        return (
          <div key={id_qq}>
            <header className="d-flex mb-2 mt-4">
              <div>
                <h4 className="mb-n1">{answer.name}</h4>
                <small>{answer.text}</small>
              </div>
              <small className="text-muted ms-auto">Ввод</small>
            </header>
            <ul>
              {oneQuestionAnswers.map((a) => {
                const inputAns = a as IQuestionInputWithAnswer;
                return <li key={inputAns.id}>{inputAns.value}</li>;
              })}
            </ul>
          </div>
        );
      })}
    </div>
  );
};

export default InterviewResults;

export const showInterviewResultsInModal = (
  id: number,
  title?: string,
  showParticipants?: boolean,
) => {
  showModal({
    title,
    children: <InterviewResults id_interview={id} showParticipants={showParticipants} />,
  });
};
